set statement_timeout='55s'; select string_agg(concat_ws('|',e.vehicle_id,to_char(coalesce(c.posted_at,e.observed_at) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS'),e.author_role,e.claim_kind,coalesce(e.polarity::text,'n'),coalesce(e.speech_act,'n'),case when e.quote ~* '(\$\s?[0-9]|[0-9]+(\.[0-9])?\s?k\b|sold|hammer|final (bid|price)|winning|reserve)' then 1 else 0 end,case when e.source_comment_id is null then 0 when c.id is null then 2 when coalesce(c.comment_type,'')='bid' or c.bid_amount is not null then 3 else 1 end, coalesce(c.auction_event_id::text,'')),E'\n') s from evidence_claims e left join auction_comments c on c.id=e.source_comment_id where e.vehicle_id::text >= '0' and e.vehicle_id::text < '4' and e.status='active'